#[target_feature(enable = "avx512f,avx")]
fn test_x86_avx512f_mm512_sqrt_ps_vs_narrow_impl() -> Result<Verdict, String> {
        if !(std::arch::is_x86_feature_detected!("avx")) {
            return Ok(Verdict::Skipped("avx not present"));
        }
    unsafe {
        let a_wide = create__m512_from([1.0f32, 2.0f32, 3.0f32, 4.0f32, 5.0f32, 6.0f32, 7.0f32, 8.0f32, 9.0f32, 10.0f32, 11.0f32, 12.0f32, 13.0f32, 14.0f32, 15.0f32, 16.0f32]);
        let a_narrow = create__m256_from([1.0f32, 2.0f32, 3.0f32, 4.0f32, 5.0f32, 6.0f32, 7.0f32, 8.0f32]);
        let wide = unpack__m512_to_f32_array(_mm512_sqrt_ps(a_wide));
        let narrow = unpack__m256_to_f32_array(_mm256_sqrt_ps(a_narrow));
        check_float_array_equality(&wide[..8], &narrow).map_err(|e| crate::cpu::with_call(e, "_mm512_sqrt_ps(a_wide) vs _mm256_sqrt_ps(a_narrow)"))?;
        Ok(Verdict::Checked)
    }
}

pub(super) fn test_x86_avx512f_mm512_sqrt_ps_vs_narrow() -> Result<Verdict, String> {
    unsafe { test_x86_avx512f_mm512_sqrt_ps_vs_narrow_impl() }
}

