#[target_feature(enable = "avx512f,sse")]
fn test_x86_avx512f_mm_mask_sqrt_ps_vs_unmasked_impl() -> Result<Verdict, String> {
        if !(std::arch::is_x86_feature_detected!("sse")) {
            return Ok(Verdict::Skipped("sse not present"));
        }
    unsafe {
        let a = create__m128_from([1.0, 2.0, 3.0, 4.0]);
        let src = create__m128_from([5.0, 6.0, 7.0, 8.0]);
        let k = create__mmask8_from(0b01010101);
        let masked = unpack__m128_to_f32_array(_mm_mask_sqrt_ps(src, k, a));
        let plain = unpack__m128_to_f32_array(_mm_sqrt_ps(a));
        let src_lanes = unpack__m128_to_f32_array(src);
        let expected: [f32; 4] = core::array::from_fn(|i| if (k >> i) & 1 == 1 { plain[i] } else { src_lanes[i] });
        check_float_array_equality(&masked, &expected).map_err(|e| crate::cpu::with_call(e, "_mm_mask_sqrt_ps(src, k, a) vs _mm_sqrt_ps(a)"))?;
        Ok(Verdict::Checked)
    }
}

