#[target_feature(enable = "avx512f,avx")]
fn test_x86_avx512f_mm256_mask_sqrt_pd_vs_unmasked_impl() -> Result<Verdict, String> {
        if !(std::arch::is_x86_feature_detected!("avx")) {
            return Ok(Verdict::Skipped("avx not present"));
        }
    unsafe {
        let a = create__m256d_from([1.0, 2.0, 3.0, 4.0]);
        let src = create__m256d_from([5.0, 6.0, 7.0, 8.0]);
        let k = create__mmask8_from(0b01010101);
        let masked = unpack__m256d_to_f64_array(_mm256_mask_sqrt_pd(src, k, a));
        let plain = unpack__m256d_to_f64_array(_mm256_sqrt_pd(a));
        let src_lanes = unpack__m256d_to_f64_array(src);
        let expected: [f64; 4] = core::array::from_fn(|i| if (k >> i) & 1 == 1 { plain[i] } else { src_lanes[i] });
        check_float_array_equality(&masked, &expected).map_err(|e| crate::cpu::with_call(e, "_mm256_mask_sqrt_pd(src, k, a) vs _mm256_sqrt_pd(a)"))?;
        Ok(Verdict::Checked)
    }
}

