        let k = create__mmask8_from(0b01010101);
        let masked = unpack__m512d_to_f64_array(_mm512_mask_sqrt_round_pd::<8>(src, k, a));
        let plain = unpack__m512d_to_f64_array(_mm512_sqrt_round_pd::<8>(a));
        let src_lanes = unpack__m512d_to_f64_array(src);
        let expected: [f64; 8] = core::array::from_fn(|i| if (k >> i) & 1 == 1 { plain[i] } else { src_lanes[i] });
